class TreeNode {
  final String symbol;
  String mark;
  final List<TreeNode> children;
  TreeNode(this.symbol, {this.mark = '', List<TreeNode>? children})
    : children = children ?? [];
}
class StackItem {
  final String symbol;
  final TreeNode? node;
  StackItem(this.symbol, [this.node]);
}
